#include <iostream>
#include <cmath>

class Point {
private:
    double x;
    double y;

public:
    // Default constructor
    Point() : x(0.0), y(0.0) {}

    // Parameterized constructor
    Point(double xVal, double yVal) : x(xVal), y(yVal) {}

    // Accessor methods (getters)
    double getX() const { return x; }
    double getY() const { return y; }

    // Mutator methods (setters)
    void setX(double xVal) { x = xVal; }
    void setY(double yVal) { y = yVal; }

    // Method to calculate distance from the origin (0,0)
    double distanceFromOrigin() const {
        return std::sqrt(x * x + y * y);
    }

    // Method to calculate distance between this point and another
    double distanceTo(const Point& other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        return std::sqrt(dx * dx + dy * dy);
    }
};

int main() {
    Point p1(3.0, 4.0);
    std::cout << "Point p1: (" << p1.getX() << ", " << p1.getY() << ")" << std::endl;
    std::cout << "Distance from origin: " << p1.distanceFromOrigin() << std::endl;

    Point p2(1.0, 1.0);
    std::cout << "Distance between p1 and p2: " << p1.distanceTo(p2) << std::endl;

    return 0;
}
